/// Otherwise, whether y is parallel to it, decided exactly: (x_j − x_i) × y = 0.
fn chord_checks(xi: [f64; 3], xj: [f64; 3], y: [f64; 3]) -> (bool, bool) {
    let mut d: Vec<ExactWideSum> = Vec::with_capacity(3);
    let mut zero = true;
    for k in 0..3 {
        let mut s = ExactWideSum::new();
        s.add_binary64(xj[k], false).expect("finite");
        s.add_binary64(xi[k], true).expect("finite");
        zero &= s.is_zero();
        d.push(s);
    }
    if zero {
        return (true, false);
    }
    let mut parallel = true;
    for (a, b) in [(1usize, 2usize), (2, 0), (0, 1)] {
        // d_a·y_b − d_b·y_a
        let mut c = ExactWideSum::new();
        if y[b] != 0.0 {
            let (neg, sig, lsb) = binary64_parts(y[b]);
            c.add_scaled(&d[a], neg, sig, lsb).expect("in span");
        }
        if y[a] != 0.0 {
            let (neg, sig, lsb) = binary64_parts(y[a]);
            c.add_scaled(&d[b], !neg, sig, lsb).expect("in span");
        }
        parallel &= c.is_zero();
    }
    (false, parallel)
}

impl PrimitiveSource {
    pub fn new(parts: SourceParts) -> Result<Self, SourceError> {
        let SourceParts {
            nodes,
            mut members,
            mut springs,
            mut directional_springs,
            mut constraints,
            mut loads,
            mut stations,
            mut supports,
        } = parts;
        // V-K seeded fault VK-F10 (§7.3-10, list-order form): the canonical
        // sort skipped (the caller's order kept).
        #[cfg(any(test, feature = "mutation-controls"))]
        let caller_order = (
            members.clone(),
            springs.clone(),
            directional_springs.clone(),
            constraints.clone(),
            loads.clone(),
            stations.clone(),
        );
        if nodes.is_empty() {
            return Err(SourceError::NoNodes);
        }
        let node_count = nodes.len();
        for (index, p) in nodes.iter().enumerate() {
            if p.iter().any(|c| !c.is_finite()) {
                return Err(SourceError::NonFiniteCoordinate { node: index as u32 });
            }
        }
        let in_range = |node: u32| -> Result<(), SourceError> {
            if (node as usize) < node_count {
                Ok(())
            } else {
                Err(SourceError::NodeOutOfRange { node })
            }
        };
        members.sort_by_key(|m| m.id);
        for pair in members.windows(2) {
            if pair[0].id == pair[1].id {
                return Err(SourceError::DuplicateMemberId { id: pair[0].id });
            }
        }
        for m in &members {
            in_range(m.node_i)?;
            in_range(m.node_j)?;
            if m.node_i == m.node_j {
                return Err(SourceError::RepeatedMemberNode { member: m.id });
            }
            use MemberProperty as P;
            property_check(m.id, P::ElasticModulus, m.elastic_modulus, false)?;
            property_check(m.id, P::ShearModulus, m.shear_modulus, false)?;
            property_check(m.id, P::Area, m.area, true)?;
            property_check(m.id, P::SecondMomentY, m.second_moment_y, true)?;
            property_check(m.id, P::SecondMomentZ, m.second_moment_z, true)?;
            property_check(m.id, P::TorsionConstant, m.torsion_constant, true)?;
            if m.y_reference.iter().any(|c| !c.is_finite()) {
                return Err(SourceError::NonFiniteProperty {
                    member: m.id,
                    property: P::YReference,
                });
            }
            let (zero, parallel) = chord_checks(
                nodes[m.node_i as usize],
                nodes[m.node_j as usize],
                m.y_reference,
            );
            if zero {
                return Err(SourceError::ZeroLength { member: m.id });
            }
            if parallel {
                return Err(SourceError::DegenerateAxis { member: m.id });
            }
        }
        springs.sort_by_key(|s| s.id);
        for pair in springs.windows(2) {
            if pair[0].id == pair[1].id {
                return Err(SourceError::DuplicateSpringId { id: pair[0].id });
            }
        }
        for s in &springs {
            in_range(s.dof.node)?;
            if !s.stiffness.is_finite() || s.stiffness <= 0.0 {
                return Err(SourceError::NonPositiveSpring { id: s.id });
            }
        }
        directional_springs.sort_by_key(|s| s.id);
        for pair in directional_springs.windows(2) {
            if pair[0].id == pair[1].id {
                return Err(SourceError::DuplicateSpringId { id: pair[0].id });
            }
        }
        for s in &directional_springs {
            in_range(s.node)?;
            if springs.iter().any(|g| g.id == s.id) {
                return Err(SourceError::DuplicateSpringId { id: s.id });
            }
            if !s.stiffness.is_finite() || s.stiffness <= 0.0 {
                return Err(SourceError::NonPositiveSpring { id: s.id });
            }
            if s.direction.iter().any(|c| !c.is_finite()) {
                return Err(SourceError::NonFiniteDirection { id: s.id });
            }
            if s.direction.iter().all(|&c| c == 0.0) {
                return Err(SourceError::ZeroDirection { id: s.id });
            }
        }
        constraints.sort_by_key(|c| c.dof);
        let mut constrained = vec![None; node_count * DOF_PER_NODE];
        for c in &constraints {
            in_range(c.dof.node)?;
            if !c.value.is_finite() {
                return Err(SourceError::NonFiniteValue { dof: c.dof });
            }
            let slot = &mut constrained[c.dof.global()];
            if slot.is_some() {
                return Err(SourceError::DuplicateConstraint { dof: c.dof });
            }
            *slot = Some(c.value);
        }
        for l in &loads {
            in_range(l.dof.node)?;
            if !l.value.is_finite() {
                return Err(SourceError::NonFiniteValue { dof: l.dof });
            }
            if l.source_id.is_empty() {
                return Err(SourceError::EmptyLoadSource { dof: l.dof });
            }
        }
        loads.sort_by(|a, b| {
            (a.dof, a.source_id.as_bytes(), a.value.to_bits()).cmp(&(
                b.dof,
                b.source_id.as_bytes(),
                b.value.to_bits(),
            ))
        });
        stations.sort_by_key(|s| s.id);
        for pair in stations.windows(2) {
            if pair[0].id == pair[1].id {
                return Err(SourceError::DuplicateStationId { id: pair[0].id });
            }
        }
        for s in &stations {
            if members.binary_search_by_key(&s.member, |m| m.id).is_err() {
                return Err(SourceError::UnknownMember {
                    station: s.id,
                    member: s.member,
                });
            }
            if !s.fraction.is_finite() || !(0.0..=1.0).contains(&s.fraction) {
                return Err(SourceError::StationOutOfRange { id: s.id });
            }
        }
        supports.sort_by_key(|s| s.id);
        for pair in supports.windows(2) {
            if pair[0].id == pair[1].id {
                return Err(SourceError::DuplicateSupportId { id: pair[0].id });
            }
        }
        for group in &mut supports {
            in_range(group.node)?;
            group.springs.sort_unstable();
            group.springs.dedup();
            group.directional_springs.sort_unstable();
            group.directional_springs.dedup();
            let bad_restraint = (0..DOF_PER_NODE).any(|c| {
                group.restrained[c] && constrained[group.node as usize * DOF_PER_NODE + c].is_none()
            });
            let bad_spring = group.springs.iter().any(|id| {
                springs
                    .binary_search_by_key(id, |s| s.id)
                    .map_or(true, |k| springs[k].dof.node != group.node)
            });
            let bad_directional = group.directional_springs.iter().any(|id| {
                directional_springs
                    .binary_search_by_key(id, |s| s.id)
                    .map_or(true, |k| directional_springs[k].node != group.node)
            });
            if bad_restraint || bad_spring || bad_directional {
                return Err(SourceError::SupportMismatch { id: group.id });
            }
        }
        // Bodies: the connected components of the member graph.
        let mut parent: Vec<usize> = (0..node_count).collect();
        fn root(parent: &mut [usize], mut x: usize) -> usize {
            while parent[x] != x {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            x
        }
        for m in &members {
            let (a, b) = (
                root(&mut parent, m.node_i as usize),
                root(&mut parent, m.node_j as usize),
            );
            if a != b {
                let (low, high) = (a.min(b), a.max(b));
                parent[high] = low;
            }
        }
        let mut body_of_root = vec![u32::MAX; node_count];
        let mut body_of_node = vec![0u32; node_count];
        let mut body_count = 0u32;
        for node in 0..node_count {
            let r = root(&mut parent, node);
            if body_of_root[r] == u32::MAX {
                body_of_root[r] = body_count;

    let mut d = [0.0f64; 3];
    for (a, extent) in d.iter_mut().enumerate() {
        let mut low = coordinates[0][a];
        let mut high = coordinates[0][a];
        for p in coordinates {
            low = low.min(p[a]);
            high = high.max(p[a]);
        }
        *extent = high - low;
    }
    ((d[0] * d[0] + d[1] * d[1]) + d[2] * d[2]).sqrt()
}

/// Item 6, in this order: tr = max(S_tr, fl(L_b·S_rot)); ro = max(S_rot,
/// fl(S_tr/L_b)); fo = max(S_fo, fl(S_mo/L_b)); mo = max(S_mo, fl(L_b·S_fo)). A
/// single-node body (L_b = 0) omits the coupled terms. `s` in `Kind` order.
pub fn coupled_scales(s: [f64; 4], extent: f64) -> [f64; 4] {
    if extent == 0.0 {
        return s;
    }
    let [tr, ro, fo, mo] = s;
    [
        tr.max(extent * ro),
        ro.max(tr / extent),
        fo.max(mo / extent),
        mo.max(extent * fo),
    ]
}

/// Item 7: σ_k(m) = fl(fl(fo/A) + fl(k·fl(mo/Z))).
pub fn stress_scale(fo: f64, mo: f64, area: f64, modulus: f64, k: f64) -> f64 {
    fo / area + k * (mo / modulus)
}

/// Item 7: k_i = fl↑(k√2·i): the nearest, then the next up when the nearest is
/// below the exact product (decided with an exact product).
pub fn intensified_k(i: f64) -> f64 {
    let k = f64::from_bits(K_SQRT2_BITS);
    let nearest = k * i;
    let exact_above = (|| -> Option<bool> {
        let mut ctx = WideContext::<4>::new(128).ok()?;
        let mut sum = ExactWideSum::new();
        sum.add_product(
            &mut ctx,
            &Wide::<4>::from_f64(k).ok()?,
            &Wide::<4>::from_f64(i).ok()?,
            false,
        )
        .ok()?;
        sum.add_binary64(nearest, true).ok()?;
        Some(sum.signum() > 0)
    })()
    .unwrap_or(false);
    if exact_above {
        next_up(nearest)
    } else {
        nearest
    }
}

/// t = fl(R·S*).
pub fn threshold(s_star: f64) -> f64 {
    f64::from_bits(FLOOR_RATIO_BITS) * s_star
}

/// b = fl↑(2^-64·S*), for S* ≥ 0: exact whenever 2^-64·S* is representable,
/// at least 2^-1074 for any 0 < S*, and 0 only at S* = 0.
pub fn absolute_bound(s_star: f64) -> f64 {
    let two64 = 18_446_744_073_709_551_616.0_f64;
    let nearest = s_star / two64;
    if nearest * two64 < s_star {
        next_up(nearest)
    } else {
        nearest
    }
}

/// The verified-accuracy class of a published row of a scaled kind.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum RowClass {
    RelativeVerified,
    /// Withheld from reliance, with its absolute bound b (bits).
    AbsoluteVerified {
        bound_bits: u64,
    },
    /// Rule 2a (no threshold).
    InputDerived,
    /// A value the publication could not give (underflow or overflow): no
    /// class; F2a decides its standing (ROOT's K4 ruling O9).
    Unpublishable,
}

/// An `absolute_verified` row's bound. D1 revision 5a.3's amendment A1
/// (ROOT's ruling on RV19-6): where 0 < S\* < 2^-988 a row can reach |q| ≈ S\*,
/// so its bound carries its own publication rounding,
/// b_row = fl↑(fl↑(2^-64·S\*) + fl↑(2^-53·|q|) + 2^-1074), the sum rounded
/// upward once, decided exactly. Elsewhere b = fl↑(2^-64·S\*) is unchanged:
/// an absolute row there has |q| < 2^-34·S\*, whose rounding is below 2^-23·b
/// (R7 §5.2); and b = 0 at S\* = 0.
pub(crate) fn row_bound(value: f64, s_star: f64) -> f64 {
    let small = f64::from_bits(0x0230_0000_0000_0000); // 2^-988
    let b = absolute_bound(s_star);
    if s_star == 0.0 || s_star >= small {
        return b;
    }
    // fl↑(2^-53·|q|): the scaling back is exact, so the comparison decides.
    let two53 = 9_007_199_254_740_992.0_f64;
    let q = value.abs();
    let nearest = q / two53;
    let rounding = if nearest * two53 < q {
        next_up(nearest)
    } else {
        nearest
    };
    // The three terms span at most 2,100 bits: the sum and its upward
    // rounding are exact (no refusal is reachable).
    (|| -> Option<f64> {
        let mut num = ExactWideSum::new();
        num.add_binary64(b, false).ok()?;
        num.add_binary64(rounding, false).ok()?;
        num.add_binary64(f64::from_bits(1), false).ok()?;
        let mut den = ExactWideSum::new();
        den.add_binary64(1.0, false).ok()?;
        let mut ctx = WideContext::<16>::new(1024).ok()?;
        directed_ratio(&mut ctx, &num, &den, Direction::Up).ok()
    })()
    .unwrap_or(f64::INFINITY)
}

/// D1 §4.1.6 item 1 on the published value: `absolute_verified` iff
/// |q| < fl(R·S\*), and always when S\* < 2^-988, with the bound of
/// `row_bound` (amendment A1).
pub fn classify(value: f64, s_star: f64) -> RowClass {
    // V-K seeded fault VK-F17 (§7.3-17): every scaled row relative_verified.
    #[cfg(any(test, feature = "mutation-controls"))]
    if super::seeded::active(super::seeded::Fault::F17) {
        return RowClass::RelativeVerified;
    }
    let small = f64::from_bits(0x0230_0000_0000_0000); // 2^-988
    if s_star < small || value.abs() < threshold(s_star) {
        RowClass::AbsoluteVerified {
            bound_bits: row_bound(value, s_star).to_bits(),
        }
    } else {
        RowClass::RelativeVerified
    }
}

