/// Closed receipt policies. Each names one semantic identity; none is chosen
/// from a caller label.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ReceiptPolicy {
    SourceBlocks,
    PhysicsSource,
    LoadReferenceSource,
}
impl ReceiptPolicy {
    fn composite(self) -> bool {
        self != Self::SourceBlocks
    }
    fn semantic_id(self) -> &'static str {
        match self {
            Self::SourceBlocks => SEMANTIC_ID,
            Self::PhysicsSource => COMPOSITE_SEMANTIC_ID,
            Self::LoadReferenceSource => LOAD_REFERENCE_SOURCE_SEMANTIC_ID,
        }
    }
    fn name(self) -> &'static str {
        match self {
            Self::SourceBlocks => "SOURCE-BLOCKS-1",
            Self::PhysicsSource => "PHYSICS-SOURCE-1",
            Self::LoadReferenceSource => "LOAD-REFERENCE-SOURCE-1",
        }
    }
    fn case_evidence_domain(self) -> &'static str {
        match self {
            Self::LoadReferenceSource => "load_reference_source_case_evidence_v1",
            _ => "physics_source_case_evidence_v1",
        }
    }
}

/// Captures the actual raw request before parsing. No parsed/hash constructor.
#[derive(Debug)]
pub(super) struct CapturedInvocation {
    raw: Value,
    mode: PreviewSolverMode,
    digest: String,
    encoded_len: usize,
}
impl CapturedInvocation {
    pub(super) fn parse(
        raw: Value,
        mode: PreviewSolverMode,
    ) -> Result<(LinearStaticPreviewRequest, Self), ReceiptError> {
        let encoded_len = checked(&raw)?.len();
        let digest = hash(
            "source_blocks_invocation_v1",

        }
        fn visit_map<A: MapAccess<'de>>(self, mut map: A) -> Result<Value, A::Error> {
            let mut seen = HashSet::new();
            let mut values = serde_json::Map::new();
            while let Some(key) = map.next_key::<String>()? {
                if !seen.insert(key.clone()) { return Err(A::Error::custom(format!("duplicate object member: {key}"))); }
                values.insert(key, map.next_value_seed(Seed)?);
            }
            Ok(Value::Object(values))
        }
    }

    let mut deserializer = serde_json::Deserializer::from_str(input);
    let value = Seed.deserialize(&mut deserializer).map_err(|e| format!("CHECKED-JSON-INVALID: {e}"))?;
    deserializer.end().map_err(|e| format!("CHECKED-JSON-INVALID: {e}"))?;
    Ok(value)
}

fn validate_checked_value(value: &Value) -> Result<(), String> {
    match value {
        Value::Number(number) => {
            if let Some(v) = number.as_i64() {
                if !(-MAX_SAFE_INTEGER..=MAX_SAFE_INTEGER).contains(&v) {
                    return Err(format!("CHECKED-JSON-UNSAFE-INTEGER: {v}"));
                }
            } else if let Some(v) = number.as_u64() {
                if v > MAX_SAFE_INTEGER as u64 { return Err(format!("CHECKED-JSON-UNSAFE-INTEGER: {v}")); }
            } else {
                let v = number.as_f64().ok_or_else(|| "CHECKED-JSON-NUMBER-INVALID".to_string())?;
                if !v.is_finite() { return Err("CHECKED-JSON-NON-FINITE".to_string()); }
                if v.fract() == 0.0 && v.abs() > MAX_SAFE_INTEGER as f64 {
                    return Err(format!("CHECKED-JSON-UNSAFE-INTEGRAL-FLOAT: {v}"));
                }
            }
        }
        Value::Array(values) => for item in values { validate_checked_value(item)?; },
        Value::Object(values) => for item in values.values() { validate_checked_value(item)?; },
        _ => {}
    }
    Ok(())
}

