// ---------------------------------------------------------------------------
// Conversion to binary64 and widening (every width, L = 2 included)
// ---------------------------------------------------------------------------

/// The correctly rounded binary64 value of a `Wide`, with its outcome (module
/// documentation).
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Binary64Outcome {
    /// A normal result, or an exact ±0 (sign kept). Rounded to nearest.
    Normal(f64),
    /// A subnormal result: absolute error at most 2^−1075, and
    /// `relative_precision` = 2^−1075/|value| rounded upward.
    Subnormal { value: f64, relative_precision: f64 },
    /// A nonzero value whose rounding is ±0. No value is returned.
    Underflow { negative: bool },
    /// A value whose rounding is ±∞. No value is returned.
    Overflow { negative: bool },
}

impl Binary64Outcome {
    /// The binary64 value, or None for underflow and overflow.
    pub fn value(&self) -> Option<f64> {
        match *self {
            Self::Normal(v) | Self::Subnormal { value: v, .. } => Some(v),
            Self::Underflow { .. } | Self::Overflow { .. } => None,
        }
    }
}

/// fl↑(1/(2k)) = 2^−1075/(k · 2^−1074), rounded upward, for 1 ≤ k < 2^52;
/// integer arithmetic only.
fn half_quantum_over(k: u64) -> f64 {
    debug_assert!(k >= 1 && k < 1 << 52);
    let d = 2 * u128::from(k);
    // d ∈ [2^(t−1), 2^t), so 1/d ∈ (2^−t, 2^−(t−1)].
    let t = 128 - d.leading_zeros() as i64;
    let (exponent, significand) = if d.is_power_of_two() {
        (-(t - 1), 1u128 << 52)
    } else {
        let numerator = 1u128 << (52 + t);
        let m = numerator.div_ceil(d);
        if m == 1u128 << 53 {
            (-(t - 1), 1u128 << 52)
        } else {
            (-t, m)
        }
    };
    let biased = (exponent + 1023) as u64;
    f64::from_bits((biased << 52) | (significand as u64 & ((1u64 << 52) - 1)))
}

impl<const L: usize> Wide<L> {
    /// The value rounded once to binary64, with its outcome (module
    /// documentation).
    #[allow(dead_code)] // K4 API (publication of retained quantities)
    pub(crate) fn to_binary64(&self) -> Binary64Outcome {
        let negative = self.negative;
        let sign = u64::from(negative) << 63;
        if is_zero_value(self) {
            return Binary64Outcome::Normal(f64::from_bits(sign));
        }
        let e = i128::from(self.exponent);
        if e > 1023 {
            return Binary64Outcome::Overflow { negative };
        }
        let mut quantum = (e - 52).max(-1074);
        // Index in the significand of the bit of weight 2^quantum.
        let index = quantum - unit_exponent(self);
        let significand = &self.significand[..];
        let mut kept = word_at(significand, index);
        let round = bit_at(significand, index - 1);
        let rest = any_below(significand, index - 1);
        if round && (rest || kept & 1 == 1) {
            kept += 1;
        }
        if kept == 1 << 53 {
            kept = 1 << 52;
            quantum += 1;
        }
        if kept == 0 {
            return Binary64Outcome::Underflow { negative };
        }
        if kept >= 1 << 52 {
            let leading = quantum + 52;
            if leading > 1023 {
                return Binary64Outcome::Overflow { negative };
            }
            let biased = (leading + 1023) as u64;
            Binary64Outcome::Normal(f64::from_bits(sign | (biased << 52) | (kept - (1 << 52))))
        } else {
            debug_assert_eq!(quantum, -1074);
            Binary64Outcome::Subnormal {
                value: f64::from_bits(sign | kept),
                relative_precision: half_quantum_over(kept),
            }
        }
    }

    /// The same value at a width M ≥ L (exact).
    #[allow(dead_code)] // K4 API (the stop rule and the p + 64 residual across widths)
    pub(crate) fn widen<const M: usize>(&self) -> Wide<M> {
        const { assert!(M >= L) };

//! Pure display conversion facade. Stored engineering quantities are never mutated.
use open_pipe_stress_units::{convert_for_dimension, unit_by_symbol, Dimension};
use serde_json::{json, Value};

/// Convert each item independently through the accepted unit catalog. Unknown
/// dimensions/units and non-finite results remain explicit unavailable entries.
pub fn convert_display_quantities(input: &Value) -> Value {
    let Some(items) = input.get("items").and_then(Value::as_array) else {
        return json!({"items":[],"error":{"code":"DISPLAY-INPUT-INVALID","message":"items must be an array"}});
    };
    let items: Vec<Value> = items.iter().map(|item| {
        let id = item.get("id").cloned().unwrap_or(Value::Null);
        let unavailable = |message: String| json!({"id":id,"status":"unavailable","message":message});
        let Some(record) = item.as_object() else { return unavailable("item must be an object".into()); };
        if record.keys().any(|key| !matches!(key.as_str(), "id"|"value"|"from_unit"|"to_unit"|"dimension_id")) {
            return unavailable("unsupported display quantity field; pressure reference changes are not display conversions".into());
        }
        if !item.get("id").is_some_and(Value::is_string) { return unavailable("id must be a string".into()); }
        let Some(value) = item.get("value").and_then(Value::as_f64).filter(|v| v.is_finite()) else { return unavailable("value must be finite".into()); };
        let Some(dimension_id) = item.get("dimension_id").and_then(Value::as_str) else { return unavailable("dimension_id must be explicit".into()); };
        let dimension = match Dimension::from_schema_value(dimension_id) { Ok(value) => value, Err(error) => return unavailable(error.to_string()) };
        let Some(from_symbol) = item.get("from_unit").and_then(Value::as_str) else { return unavailable("from_unit must be explicit".into()); };
        let Some(to_symbol) = item.get("to_unit").and_then(Value::as_str) else { return unavailable("to_unit must be explicit".into()); };
        let from = match unit_by_symbol(from_symbol, dimension) { Ok(value) => value, Err(error) => return unavailable(error.to_string()) };
        let to = match unit_by_symbol(to_symbol, dimension) { Ok(value) => value, Err(error) => return unavailable(error.to_string()) };
        match convert_for_dimension(value, dimension, from, to) {
            Ok(converted) if converted.is_finite() => json!({"id":id,"status":"converted","value":converted,"unit":to_symbol}),
            Ok(_) => unavailable("display conversion result is not finite".into()),
            Err(error) => unavailable(error.to_string()),
        }
    }).collect();
    json!({"items":items})
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn display_conversion_is_pure_and_distinguishes_absolute_and_interval_temperature() {
        let input = json!({"items":[
            {"id":"length","value":1,"from_unit":"m","to_unit":"mm","dimension_id":"length"},
            {"id":"absolute","value":0,"from_unit":"degC","to_unit":"degF","dimension_id":"temperature"},
            {"id":"interval","value":10,"from_unit":"degC","to_unit":"degF","dimension_id":"temperature_interval"},
            {"id":"wrong","value":1,"from_unit":"m","to_unit":"Pa","dimension_id":"length"},
            {"id":"unknown","value":1,"from_unit":"TBD","to_unit":"mm","dimension_id":"length"}
        ]});
        let original = input.clone();
        let output = convert_display_quantities(&input);
        assert_eq!(input, original);
        assert_eq!(output["items"][0]["value"], 1000.0);
        assert!((output["items"][1]["value"].as_f64().unwrap() - 32.0).abs() < 1e-8);
        assert!((output["items"][2]["value"].as_f64().unwrap() - 18.0).abs() < 1e-8);
        assert_eq!(output["items"][3]["status"], "unavailable");
        assert_eq!(output["items"][4]["status"], "unavailable");
    }
    #[test]
    fn same_unit_display_preserves_small_values_and_still_validates_metadata() {
        let stress = f64::from_bits(0x3fd12345679b3fe0);
        let input = json!({"items":[
            {"id":"absolute","value":1e-16,"from_unit":"degC","to_unit":"degC","dimension_id":"temperature"},
            {"id":"alias","value":-1e-16,"from_unit":"C","to_unit":"degC","dimension_id":"temperature"},
            {"id":"stress","value":stress,"from_unit":"MPa","to_unit":"MPa","dimension_id":"stress"},
            {"id":"wrong","value":1,"from_unit":"m","to_unit":"m","dimension_id":"force"},
            {"id":"unknown","value":1,"from_unit":"invalid","to_unit":"invalid","dimension_id":"temperature"},
            {"id":"reference","value":1,"from_unit":"bar","to_unit":"bar","dimension_id":"pressure","reference":"gauge"}
        ]});
        let original = input.clone();
        let output = convert_display_quantities(&input);
        for index in 0..3 {
            assert_eq!(output["items"][index]["status"], "converted");
            assert_eq!(output["items"][index]["value"].as_f64().unwrap().to_bits(), input["items"][index]["value"].as_f64().unwrap().to_bits());
        }
        for index in 3..6 { assert_eq!(output["items"][index]["status"], "unavailable"); }
        assert_eq!(input, original);
    }

    #[test]
    fn display_conversion_rejects_pressure_reference_payload_and_overflow() {
        let output = convert_display_quantities(&json!({"items":[
            {"id":"pressure","value":1,"from_unit":"Pa","to_unit":"psi","dimension_id":"pressure","reference":"gauge"},
            {"id":"overflow","value":1e308,"from_unit":"m","to_unit":"mm","dimension_id":"length"}
        ]}));
        assert!(output["items"]
            .as_array()
            .unwrap()
            .iter()
            .all(|item| item["status"] == "unavailable"));
    }
}

pub fn convert_for_dimension(
    value: f64,
    dimension: Dimension,
    from: UnitId,
    to: UnitId,
) -> Result<f64, UnitError> {
    validate_finite("quantity", value)?;
    let from_def = from.definition();
    let to_def = to.definition();
    if !unit_supports_dimension(from_def.dimension, dimension) {
        return Err(UnitError::DimensionMismatch {
            expected: dimension,
            actual: from_def.dimension,
        });
    }
    if !unit_supports_dimension(to_def.dimension, dimension) {
        return Err(UnitError::DimensionMismatch {
            expected: dimension,
            actual: to_def.dimension,
        });
    }
    if dimension == Dimension::Tbd {
        return Err(UnitError::UnresolvedDimension);
    }
    // Identity is exact after all finite and semantic dimension checks. Routing
    // through an affine offset or scale and back can erase small values or bits.
    if from == to {
        return Ok(value);
    }
    let canonical_value = from_def.transform_to_canonical.to_canonical(value);
    Ok(to_def
        .transform_to_canonical
        .canonical_to_unit(canonical_value))
}
